package org.agentfrc.lesson;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import edu.wpi.first.wpilibj.simulation.*;
class TractionTest {
 static double sideJ,mu;static byte[] contactBytes;static Path out;
 @BeforeAll static void setup()throws Exception{CoupledDriveTest.setup();out=CoupledDriveTest.out;String input=System.getenv("FRC_TRACTION_ASSUMPTIONS");assertNotNull(input);contactBytes=Files.readAllBytes(Path.of(input));Properties c=new Properties();c.load(new java.io.ByteArrayInputStream(contactBytes));assertEquals(Set.of("schema","basis","sideRotationalInertiaKgM2","frictionCoefficient","frictionUncertainty","normalLoadAllocation","surface","chassisCadBinding","engineeringAcceptance"),c.stringPropertyNames());assertEquals("frc-straight-traction-hypothesis/v1",c.getProperty("schema"));assertEquals("unvalidated-two-effective-side-contacts",c.getProperty("basis"));assertEquals("unknown",c.getProperty("frictionUncertainty"));assertEquals("equal-halves-of-assumed-mg",c.getProperty("normalLoadAllocation"));assertEquals("level-rigid-straight-only",c.getProperty("surface"));assertEquals("unavailable",c.getProperty("chassisCadBinding"));assertEquals("blocked",c.getProperty("engineeringAcceptance"));sideJ=Double.parseDouble(c.getProperty("sideRotationalInertiaKgM2"));mu=Double.parseDouble(c.getProperty("frictionCoefficient"));}
 @BeforeEach void enable(){DriverStationSim.resetData();DriverStationSim.setDsAttached(true);DriverStationSim.setEnabled(true);DriverStationSim.notifyNewData();}
 @AfterEach void disable(){DriverStationSim.setEnabled(false);DriverStationSim.notifyNewData();RoboRioSim.setVInVoltage(12);}
 static StraightSlipRig rig(double friction,NeoEvidenceProfile profile){return new StraightSlipRig(CoupledDriveTest.params,sideJ,friction,CoupledDriveTest.inertia,profile);}
 @Test void independentStickImpulseAndActionReaction(){var c=new LongitudinalContact(2,.1,.01,2);var s=c.resolve(0,.1,.1,.001);assertEquals(.005,s.leftImpulse(),1e-12);assertEquals(.005,s.rightImpulse(),1e-12);assertEquals(.005,s.velocity(),1e-12);assertEquals(.05,s.leftOmega(),1e-12);assertEquals(0,s.leftSlip(),1e-12);assertEquals(.00005,s.lossJ(),1e-12);assertEquals(s.leftImpulse()+s.rightImpulse(),2*s.velocity(),1e-12);assertEquals(-.1*s.leftImpulse(),.01*(s.leftOmega()-.1),1e-12);assertTrue(s.kktResidual()<1e-10);var mixed=new LongitudinalContact(2,.1,.01,.5).resolve(0,.2,0,.001);double cap=.5*2*LongitudinalContact.G*.5*.001;assertEquals(cap,mixed.leftImpulse(),1e-12);assertEquals(-cap/3,mixed.rightImpulse(),1e-12);assertEquals(0,mixed.rightSlip(),1e-12);assertTrue(mixed.leftSlip()>0);var reverse=c.resolve(0,-.1,-.1,.001);assertEquals(-s.leftImpulse(),reverse.leftImpulse(),1e-12);assertEquals(s.lossJ(),reverse.lossJ(),1e-12);}
 @Test void zeroInputHasNoArtificialCreep(){var c=new LongitudinalContact(45,.0762,.02,.8);for(int i=0;i<100;i++){var s=c.resolve(0,0,0,.001);assertEquals(0,s.velocity());assertEquals(0,s.leftOmega());assertEquals(0,s.lossJ());}}
 @Test void zeroFrictionSpinsWheelsWithoutMovingBody(){try(var rig=rig(0,NeoEvidenceProfile.WPILIB_2026_2_1_PRODUCT_SPEC)){StraightSlipRig.Sample s=null;for(int i=0;i<5;i++)s=rig.step(true,2,.6,20);assertEquals(0,s.x(),1e-12);assertEquals(0,s.velocity(),1e-12);assertEquals(0,s.leftForce(),1e-12);assertTrue(s.wheelSurfaceSpeed()>1&&s.encoderDistance()>0);assertEquals(s.wheelSurfaceSpeed(),s.encoderRate(),1e-8);}
  var rejected=assertThrows(IllegalArgumentException.class,()->{try(var rig=rig(0,NeoEvidenceProfile.WPILIB_2026_2_1_PRODUCT_SPEC)){for(int i=0;i<25;i++)rig.step(true,2,.6,20);}});assertEquals("Unsupported regeneration",rejected.getMessage());}
 @Test void cappedTractionSeparatesEncoderTravelFromGround(){try(var rig=rig(.05,NeoEvidenceProfile.WPILIB_2026_2_1_PRODUCT_SPEC)){StraightSlipRig.Sample s=null;double prior=0;for(int i=0;i<50;i++){s=rig.step(true,2,.6,20);assertTrue(Math.abs(s.leftForce())<=.05*45*LongitudinalContact.G/2+1e-8);assertTrue((s.velocity()-prior)/.02<=.05*LongitudinalContact.G+1e-8);assertTrue(s.contactLossJ()>=-1e-9);assertEquals(0,s.mechanicalResidual(),1e-6);assertEquals(s.wheelSurfaceSpeed(),s.encoderRate(),1e-8);assertEquals(s.wheelDistance(),s.encoderDistance(),2*Math.PI*.0762/2048/2+1e-9,"Independent raw encoder count quantization");prior=s.velocity();}assertTrue(s.encoderDistance()-s.x()>.1);assertTrue(s.slip()>0);}}
 @Test void reactionTorqueLoadsMotorAndSharedBattery(){StraightSlipRig.Sample ice=null,loaded=null;try(var rig=rig(0,NeoEvidenceProfile.WPILIB_2026_2_1_PRODUCT_SPEC)){for(int i=0;i<5;i++)ice=rig.step(true,2,.6,20);}try(var rig=rig(mu,NeoEvidenceProfile.WPILIB_2026_2_1_PRODUCT_SPEC)){for(int i=0;i<5;i++)loaded=rig.step(true,2,.6,20);}assertTrue(ice.wheelSurfaceSpeed()>loaded.wheelSurfaceSpeed());assertTrue(loaded.batteryAmps()>ice.batteryAmps());assertTrue(loaded.bus()<ice.bus());assertTrue(loaded.x()>ice.x());}
 static List<StraightSlipRig.Sample> trajectory(int substeps){List<StraightSlipRig.Sample> list=new ArrayList<>();try(var rig=rig(mu,NeoEvidenceProfile.WPILIB_2026_2_1_PRODUCT_SPEC)){for(int i=0;i<50;i++)list.add(rig.step(true,2,.6,substeps));}return list;}
 @Test void launchSlipStickAndTimestepRefinementWithNativeBinding()throws Exception{
  var a=trajectory(20);var b=trajectory(40);boolean slipped=false,stuck=false;double dx=0,dv=0,dw=0,db=0,di=0;StringBuilder csv=new StringBuilder("tick,bodyXM,bodyMps,wheelMps,encoderDistanceM,slipMps,leftForceN,busV,batteryA,contactLossJ,projectionLossJ\n");
  for(int i=0;i<a.size();i++){var x=a.get(i);var y=b.get(i);slipped|=Math.abs(x.slip())>1e-4;stuck|=i>5&&Math.abs(x.slip())<1e-8;dx=Math.max(dx,Math.abs(x.x()-y.x()));dv=Math.max(dv,Math.abs(x.velocity()-y.velocity()));dw=Math.max(dw,Math.abs(x.wheelSurfaceSpeed()-y.wheelSurfaceSpeed()));db=Math.max(db,Math.abs(x.bus()-y.bus()));di=Math.max(di,Math.abs(x.batteryAmps()-y.batteryAmps()));csv.append(i).append(',').append(x.x()).append(',').append(x.velocity()).append(',').append(x.wheelSurfaceSpeed()).append(',').append(x.encoderDistance()).append(',').append(x.slip()).append(',').append(x.leftForce()).append(',').append(x.bus()).append(',').append(x.batteryAmps()).append(',').append(x.contactLossJ()).append(',').append(x.projectionLossJ()).append('\n');}
  assertTrue(slipped&&stuck,"Declared launch must exercise sliding and sticking");assertTrue(dx<.01&&dv<.03&&dw<.03&&db<.2&&di<5,"Development refinement limits");assertTrue(b.get(49).projectionLossJ()<a.get(49).projectionLossJ(),"Projection dissipation must shrink with timestep");Files.writeString(out.resolve("traction-trace.csv"),csv.toString(),StandardOpenOption.CREATE_NEW);
  Properties result=new Properties();result.setProperty("cadPropertiesSha256",CoupledDriveTest.sha(CoupledDriveTest.nativeProperties));result.setProperty("tractionAssumptionsSha256",CoupledDriveTest.sha(contactBytes));result.setProperty("controllerClassSha256",CoupledDriveTest.sha(CoupledDriveController.class.getResourceAsStream("CoupledDriveController.class").readAllBytes()));result.setProperty("maxPositionDifferenceM",Double.toString(dx));result.setProperty("maxBodySpeedDifferenceMps",Double.toString(dv));result.setProperty("maxWheelSpeedDifferenceMps",Double.toString(dw));result.setProperty("maxBusDifferenceV",Double.toString(db));result.setProperty("maxCurrentDifferenceA",Double.toString(di));result.setProperty("engineeringAcceptance","blocked");result.setProperty("calibration","none");
  for(var profile:NeoEvidenceProfile.values()){var motor=profile.motor(1);result.setProperty(profile.name()+".volts",Double.toString(motor.nominalVoltageVolts));result.setProperty(profile.name()+".stallAmps",Double.toString(motor.stallCurrentAmps));result.setProperty(profile.name()+".stallTorqueNm",Double.toString(motor.stallTorqueNewtonMeters));result.setProperty(profile.name()+".freeAmps",Double.toString(motor.freeCurrentAmps));result.setProperty(profile.name()+".freeRpm",Double.toString(motor.freeSpeedRadPerSec*60/(2*Math.PI)));}
  try(var stream=Files.newOutputStream(out.resolve("traction-result.properties"),StandardOpenOption.CREATE_NEW)){result.store(stream,"Original uncalibrated straight contact model; mechanical-only work audit");}
 }
 @Test void completeMotorProfilesRemainSeparate()throws Exception{
  var old=NeoEvidenceProfile.WPILIB_2026_2_1_PRODUCT_SPEC.motor(1);var relative=NeoEvidenceProfile.REV_RELATIVE_DYNO_UNCALIBRATED.motor(1);assertEquals(105,old.stallCurrentAmps);assertEquals(2.6,old.stallTorqueNewtonMeters);assertEquals(160,relative.stallCurrentAmps);assertEquals(3,relative.stallTorqueNewtonMeters);assertEquals(2.065,relative.freeCurrentAmps);assertEquals(5820,relative.freeSpeedRadPerSec*60/(2*Math.PI),1e-9);
  StringBuilder csv=new StringBuilder("profile,xM,wheelMps,busV,batteryA,calibration\n");double[] currents=new double[2];int index=0;for(var profile:NeoEvidenceProfile.values()){try(var rig=rig(mu,profile)){StraightSlipRig.Sample s=null;for(int i=0;i<3;i++)s=rig.step(true,2,.6,20);currents[index++]=s.batteryAmps();csv.append(profile.name()).append(',').append(s.x()).append(',').append(s.wheelSurfaceSpeed()).append(',').append(s.bus()).append(',').append(s.batteryAmps()).append(",none\n");}}assertTrue(Math.abs(currents[0]-currents[1])>.1);Files.writeString(out.resolve("motor-profile-sensitivity.csv"),csv.toString(),StandardOpenOption.CREATE_NEW);
 }
 @Test void unknownOrNonfiniteContactInputsAreNotAccepted(){assertThrows(IllegalArgumentException.class,()->new LongitudinalContact(45,.0762,.02,Double.NaN));assertThrows(IllegalArgumentException.class,()->new LongitudinalContact(45,.0762,.02,-1));assertThrows(IllegalArgumentException.class,()->new LongitudinalContact(45,.0762,0,.8));assertThrows(IllegalArgumentException.class,()->new LongitudinalContact(45,.0762,.02,.8).resolve(0,0,0,0));}
}
